import sys

def main():
    data = sys.stdin.read().split()
    n = int(data[0])
    h = list(map(int, data[1:1 + n]))
    l, r = 0, n - 1
    lm = rm = 0
    total = 0
    while l < r:
        if h[l] < h[r]:
            if h[l] >= lm:
                lm = h[l]
            else:
                total += lm - h[l]
            l += 1
        else:
            if h[r] >= rm:
                rm = h[r]
            else:
                total += rm - h[r]
            r -= 1
    print(total)

main()

