def gen(rng):
    def fmt(h):
        return str(len(h)) + '\n' + ' '.join(map(str, h))

    tests = [
        fmt([0]), fmt([7]), fmt([3, 3, 3]), fmt([1, 2, 3, 4, 5]), fmt([5, 4, 3, 2, 1]),
        fmt([5, 0, 5]), fmt([0, 0, 0, 0]), fmt([2, 0, 2, 0, 2]), fmt([4, 2, 0, 3, 2, 5]),
    ]
    for n in (3, 5, 8, 10, 15, 20, 30, 40):
        for hi in (3, 9):
            tests.append(fmt([rng.randint(0, hi) for _ in range(n)]))
    big_start = len(tests)
    N = 10**5
    tests.append(fmt([rng.randint(0, 10**5) for _ in range(N)]))
    tests.append(fmt([10**5] + [0] * (N - 2) + [10**5]))
    tests.append(fmt([(10**5 if i % 2 == 0 else 0) for i in range(N)]))
    tests.append(fmt([abs(N // 2 - i) * 2 for i in range(N)]))
    tests.append(fmt([rng.randint(0, 5) for _ in range(N)]))
    return tests[:6] + tests[big_start:] + tests[6:big_start]

